'use strict';

const fs = require('fs');
const [n, k] = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);

const MOD = 1000000007;
const BASE = 4194304;

if (k >= n) {
    console.log('0');
    process.exit(0);
}

function mulMod(a, b) {
    const high = Math.floor(b / BASE);
    const low = b - high * BASE;
    return ((a * low) % MOD + ((a * high) % MOD) * BASE) % MOD;
}

const inv = new Int32Array(n + 1);
const p = new Int32Array(n + 1);

inv[1] = 1;
p[0] = 1;

const limit = n - k - 1;
let sum = 1;
let factorial = 1;

for (let i = 1; i <= n; i++) {
    if (i >= 2) {
        const q = Math.floor(MOD / i);
        const r = MOD - q * i;
        inv[i] = MOD - mulMod(q, inv[r]);
    }

    if (i <= k) {
        p[i] = 1;
    } else {
        let value = p[i - 1] - mulMod(p[i - k - 1], inv[i]);
        if (value < 0) value += MOD;
        p[i] = value;
    }

    if (i <= limit) {
        sum += p[i];
        if (sum >= MOD) sum -= MOD;
    }

    if (i <= n - 1) {
        factorial = (factorial * i) % MOD;
    }
}

const oneMinus = (1 - p[n] + MOD) % MOD;
const term = (oneMinus * n) % MOD;
const badFactor = (term - sum + MOD) % MOD;
const answer = mulMod(factorial, badFactor);

console.log(String(answer));

